_EMBEDDED_V575_SOURCE = base64.b64decode("""""").decode("utf-8")

v575 = types.ModuleType("_v576_embedded_controller")
v575.__file__ = "<embedded-v575-controller>"
# dataclasses requires the executing module to be registered in sys.modules.
sys.modules[v575.__name__] = v575
v575.__file__ = "<embedded-v575-controller>"
exec(compile(_EMBEDDED_V575_SOURCE, v575.__file__, "exec"), v575.__dict__)


@dataclass
class Job:
    index: int
    total: int
    seed: int
    policy: str


_PRINT_LOCK = Lock()


def log(message: str) -> None:
    with _PRINT_LOCK:
        print(message, flush=True)


def connect_readonly(path: str) -> sqlite3.Connection:
    # URI read-only connection. WAL is not enabled or modified.
    uri = "file:" + os.path.abspath(path).replace("\\", "/") + "?mode=ro"
    con = sqlite3.connect(
        uri,
        uri=True,
        check_same_thread=False,
        timeout=30.0,
    )
    con.row_factory = sqlite3.Row
    con.execute("PRAGMA query_only=ON")
    con.execute("PRAGMA busy_timeout=30000")
    return con


def discover_edge_columns(con):
    """Resolve subject/relation/object columns from the actual edges schema."""
    cols = [
        row[1] for row in con.execute("PRAGMA table_info(edges)").fetchall()
    ]
    if not cols:
        raise RuntimeError("Table 'edges' does not exist or has no columns")

    lower = {c.lower(): c for c in cols}

    def pick(names):
        for n in names:
            if n in lower:
                return lower[n]
        return None

    subject = pick([
        "subject", "subj", "source", "src", "s",
        "subject_id", "source_id",
    ])
    relation = pick([
        "predicate", "relation", "rel", "property", "r",
        "predicate_id", "relation_id",
    ])
    obj = pick([
        "object", "obj", "target", "dst", "o",
        "object_id", "target_id",
    ])

    # If conventional names aren't present, use the first three columns only
    # when they are unambiguous. This is preferable to silently guessing.
    if not (subject and relation and obj):
        raise RuntimeError(
            "Could not resolve edges S/R/O columns. "
            f"Actual columns: {cols}"
        )

    return subject, relation, obj


def discover_oracle(args, con):
    """
    Self-contained oracle construction using the real edges schema.

    V590 never assumes columns are literally named s/r/o. The resolved mapping
    is printed and then reused for all graph access.
    """
    subject, relation, obj = discover_edge_columns(con)

    print("")
    print("=== EDGE SCHEMA ===", flush=True)
    print(f"subject            : {subject}", flush=True)
    print(f"relation           : {relation}", flush=True)
    print(f"object             : {obj}", flush=True)

    q_ident = lambda x: '"' + x.replace('"', '""') + '"'
    S, R, O = map(q_ident, (subject, relation, obj))

    preferred = [
        "schema:location",
        "schema:birthPlace",
        "schema:nationality",
        "schema:knowsLanguage",
        "birthPlace",
        "is_a",
        "yago:hasMother",
        "team",
        "schema:inLanguage",
    ]

    existing = {
        row[0] for row in con.execute(
            f"SELECT DISTINCT {R} FROM edges WHERE {R} IS NOT NULL"
        )
    }

    counts = dict(
        con.execute(
            f"SELECT {R}, COUNT(*) FROM edges "
            f"WHERE {R} IS NOT NULL GROUP BY {R}"
        ).fetchall()
    )

    targets = [r for r in preferred if r in existing]

    ranked = sorted(
        ((r, n) for r, n in counts.items() if r not in targets),
        key=lambda x: (-x[1], str(x[0])),
    )
    target_n = max(1, min(args.top_predicates, len(counts)))
    for r, _ in ranked:
        if len(targets) >= target_n:
            break
        targets.append(r)

    targets = targets[:target_n]

    print("")
    print("=== ORACLE ===", flush=True)
    print(f"target relations : {len(targets)}", flush=True)

    cases = []
    supported = 0
    negatives = 0
    per_rel = max(
        1,
        min(
            args.supported_per_relation,
            args.negative_per_relation,
        ),
    )

    for rel in targets:
        rows = con.execute(
            f"SELECT {S}, {O} FROM edges "
            f"WHERE {R}=? AND {S} IS NOT NULL AND {O} IS NOT NULL "
            f"LIMIT ?",
            (rel, max(args.sample_each, per_rel * 4)),
        ).fetchall()

        if not rows:
            continue

        positives = rows[:per_rel]
        for s, o in positives:
            cases.append({
                "subject": s,
                "relation": rel,
                "object": o,
                "label": 1,
                "positive": True,
            })
            supported += 1

        # Prefer same-subject alternatives as hard negatives.
        for s, true_o in positives:
            neg_rows = con.execute(
                f"SELECT {O} FROM edges "
                f"WHERE {S}=? AND {R}=? AND {O}<>? "
                f"AND {O} IS NOT NULL LIMIT ?",
                (s, rel, true_o, max(4, args.negative_per_relation)),
            ).fetchall()

            if not neg_rows:
                neg_rows = con.execute(
                    f"SELECT {O} FROM edges "
                    f"WHERE {S}=? AND {R}<>? AND {O} IS NOT NULL LIMIT ?",
                    (s, rel, max(4, args.negative_per_relation)),
                ).fetchall()

            if not neg_rows:
                continue

            no = neg_rows[0][0]
            cases.append({
                "subject": s,
                "relation": rel,
                "object": no,
                "label": 0,
                "positive": False,
                "hard_negative": True,
            })
            negatives += 1

    if args.case_cap:
        cap = args.case_cap * max(1, len(targets))
        cases = cases[:cap]

    print(f"supported        : {supported}", flush=True)
    print(f"hard negatives   : {negatives}", flush=True)
    print(f"total             : {len(cases)}", flush=True)
    for r in targets:
        print(f"  {r}", flush=True)

    return cases, {}


def load_profiles(args):
    """
    Load V568 JSON directly. Supports the common profile layouts used by the
    preceding experiments without importing any prior-version code.
    """
    path = Path(args.v568)
    if not path.exists():
        raise FileNotFoundError(path)

    data = json.loads(path.read_text(encoding="utf-8"))

    if isinstance(data, dict):
        candidates = [
            data.get("profiles"),
            data.get("relations"),
            data.get("predicates"),
            data.get("results"),
        ]
        for obj in candidates:
            if isinstance(obj, dict):
                return obj
            if isinstance(obj, list):
                out = {}
                for item in obj:
                    if isinstance(item, dict):
                        key = (
                            item.get("predicate")
                            or item.get("relation")
                            or item.get("name")
                        )
                        if key:
                            out[key] = item
                if out:
                    return out

        # Direct predicate -> profile mapping.
        if all(isinstance(v, (dict, list, int, float, str))
               for v in data.values()):
            return data

    if isinstance(data, list):
        out = {}
        for item in data:
            if isinstance(item, dict):
                key = (
                    item.get("predicate")
                    or item.get("relation")
                    or item.get("name")
                )
                if key:
                    out[key] = item
        return out

    return {}


def make_job_cases(cases, seed):
    # Keep case order identical across jobs. Seed only controls the controller.
    return list(cases)



class GDStats:
    def __init__(self):
        self.expansions = 0
        self.generated = 0
        self.pruned = 0
        self.cache_hits = 0
        self.cache_misses = 0
        self.batch_queries = 0
        self.proof_checks = 0
        self.target_edge_hits = 0
        self.endpoint_hits = 0
        self.max_frontier = 0
        self.depth_hist = {}
        self.aborted = 0


def _edge_batch(
    con,
    nodes,
    per_node,
    hidden,
    stats,
    cache,
):
    """
    Bounded batch fetch. Cache is per job and stores only outgoing adjacency.
    """
    nodes = list(dict.fromkeys(nodes))
    result = {}
    misses = []

    hidden_map = defaultdict(set)
    for s, r, o in hidden:
        hidden_map[s].add((r, o))

    for node in nodes:
        if node in cache:
            stats.cache_hits += 1
            raw = cache[node]
            excluded = hidden_map.get(node)
            result[node] = [
                e for e in raw
                if not excluded or (e[0], e[1]) not in excluded
            ]
        else:
            stats.cache_misses += 1
            misses.append(node)

    for i in range(0, len(misses), 200):
        chunk = misses[i:i + 200]
        if not chunk:
            continue

        placeholders = ",".join("?" * len(chunk))
        q = f"""
            SELECT subject, relation, object, source
            FROM edges
            WHERE subject IN ({placeholders})
        """
        stats.batch_queries += 1

        grouped = defaultdict(list)
        for row in con.execute(q, chunk):
            s = str(row["subject"])
            bucket = grouped[s]
            if len(bucket) < per_node:
                bucket.append((
                    str(row["relation"]),
                    str(row["object"]),
                    row["source"],
                ))

        for node in chunk:
            cache[node] = grouped.get(node, ())
            raw = cache[node]
            excluded = hidden_map.get(node)
            result[node] = [
                e for e in raw
                if not excluded or (e[0], e[1]) not in excluded
            ]

    return result


def _relation_prior(
    profiles,
    source_relation,
    target_relation,
):
    if not source_relation:
        return 0.0
    profile = profiles.get(source_relation)
    if not profile:
        return 0.0

    second = v575.second_profile(profile)
    return float(second.get(target_relation, 0.0))


def _target_family_score(
    relation,
    target_relation,
    profiles,
    neighbors,
):
    if relation == target_relation:
        return 1.0

    return float(
        v575.target_family(
            relation,
            target_relation,
            profiles,
            neighbors,
        )
    )


def goal_directed_policy(
    con,
    cases,
    budget,
    per_node,
    max_depth,
    profiles,
    neighbors,
    seed,
    max_case_seconds,
    progress_every,
):
    # V590 CASE ADAPTER
    # Normalize raw oracle dictionaries before any case attribute access.
    normalized_cases = []

    class _GoalCase:
        __slots__ = (
            "subject", "target_relation", "object",
            "source_predicate", "kind", "gold", "path",
        )

        def __init__(
            self,
            subject,
            target_relation,
            object,
            source_predicate,
            kind,
            gold,
            path,
        ):
            self.subject = subject
            self.target_relation = target_relation
            self.object = object
            self.source_predicate = source_predicate
            self.kind = kind
            self.gold = gold
            self.path = path

    for c in cases:
        if not isinstance(c, dict):
            normalized_cases.append(c)
            continue

        relation = c.get("target_relation", c.get("relation"))
        subject = c.get("subject")
        object_ = c.get("object")

        if subject is None or relation is None or object_ is None:
            raise RuntimeError(
                "Malformed goal-directed case: "
                f"keys={sorted(c)}"
            )

        gold = bool(
            c.get(
                "gold",
                c.get(
                    "label",
                    c.get("positive", False),
                ),
            )
        )

        normalized_cases.append(
            _GoalCase(
                subject=str(subject),
                target_relation=str(relation),
                object=str(object_),
                source_predicate=str(
                    c.get("source_predicate", relation)
                ),
                kind=str(
                    c.get(
                        "kind",
                        "SUPPORTED" if gold else "HARD_NEGATIVE",
                    )
                ),
                gold=gold,
                path=tuple(
                    tuple(edge) for edge in c.get("path", ())
                ),
            )
        )

    cases = normalized_cases

    """
    Goal-directed bounded beam search.

    Unlike the previous multi-depth controllers, this does not continuously
    allocate over thousands of live hypotheses. At every depth it:
      - batch-fetches the current beam,
      - ranks edges against the actual target relation/object,
      - keeps only the best beam_width states,
      - and immediately verifies exact target edges.

    This is deliberately designed to test whether explicit goal conditioning
    is the missing ingredient.
    """
    started = time.perf_counter()
    rng = random.Random(seed)

    total = len(cases)
    correct = 0
    supported = sum(
        1
        for c in cases
        if c.gold
    )
    negatives = total - supported
    supported_correct = 0
    false_positive = 0
    predicted_positive = 0
    total_steps = 0
    path_lengths = []

    per_job_cache = {}
    beam_width = 16
    edge_width = max(8, min(per_node, 24))

    case_reports = []
    stats_total = GDStats()

    for idx, case in enumerate(cases, 1):
        if time.perf_counter() - started > (max_case_seconds * max(1, total)):
            stats_total.aborted += 1
            break

        case_started = time.perf_counter()
        hidden = {
            (
                case.subject,
                case.target_relation,
                case.object,
            )
        } if case.gold else set()

        # state = (node, path, score, last_relation, visited)
        beam = [
            (
                case.subject,
                (),
                0.0,
                None,
                frozenset([case.subject]),
            )
        ]

        found = False
        found_path = ()
        steps = 0
        best_seen = {}

        for depth in range(1, max_depth + 1):
            if time.perf_counter() - case_started > max_case_seconds:
                stats_total.aborted += 1
                break

            frontier_nodes = [state[0] for state in beam]
            adjacency = _edge_batch(
                con,
                frontier_nodes,
                edge_width,
                hidden,
                stats_total,
                per_job_cache,
            )

            candidates = []

            for node, path, parent_score, last_relation, visited in beam:
                edges = adjacency.get(node, ())

                # The query itself supplies a strong target prior.
                for relation, obj, source in edges:
                    steps += 1
                    stats_total.expansions += 1

                    exact_edge = (
                        relation == case.target_relation
                        and obj == case.object
                    )
                    endpoint = (
                        1.0
                        if obj == case.object
                        else 0.0
                    )
                    target_relation = (
                        1.0
                        if relation == case.target_relation
                        else 0.0
                    )

                    if target_relation:
                        stats_total.target_edge_hits += 1
                    if endpoint:
                        stats_total.endpoint_hits += 1

                    transition = _relation_prior(
                        profiles,
                        last_relation,
                        case.target_relation,
                    )

                    family = _target_family_score(
                        relation,
                        case.target_relation,
                        profiles,
                        neighbors,
                    )

                    revisit_penalty = (
                        0.35
                        if obj in visited
                        else 0.0
                    )

                    # Lower branching cost is preferred, but target matching
                    # overwhelmingly dominates generic graph popularity.
                    branch_cost = math.log1p(
                        len(edges)
                    ) / math.log1p(
                        max(2, edge_width)
                    )

                    depth_cost = 0.12 * depth

                    score = (
                        parent_score
                        + 4.0 * endpoint
                        + 3.2 * target_relation
                        + 1.35 * transition
                        + 0.75 * family
                        - 0.55 * branch_cost
                        - depth_cost
                        - revisit_penalty
                    )

                    # Stable tiny tie-break per seed.
                    score += (
                        (
                            hash(
                                (
                                    seed,
                                    case.subject,
                                    case.target_relation,
                                    obj,
                                    relation,
                                    depth,
                                )
                            ) & 1023
                        ) * 1e-8
                    )

                    new_path = path + (
                        (
                            node,
                            relation,
                            obj,
                        ),
                    )

                    if exact_edge:
                        found = True
                        found_path = new_path
                        break

                    if depth >= max_depth:
                        continue

                    if obj in visited:
                        stats_total.pruned += 1
                        continue

                    state_key = (
                        obj,
                        tuple(r for _, r, _ in new_path[-2:]),
                    )

                    prior = best_seen.get(
                        state_key
                    )
                    if prior is not None and prior >= score:
                        stats_total.pruned += 1
                        continue

                    best_seen[state_key] = score

                    candidates.append(
                        (
                            score,
                            obj,
                            new_path,
                            relation,
                            visited | {obj},
                        )
                    )
                    stats_total.generated += 1

                if found:
                    break

            if found:
                break

            # Hard bounded beam. This is the key anti-explosion mechanism.
            candidates.sort(
                key=lambda x: x[0],
                reverse=True,
            )
            beam = candidates[:beam_width]
            stats_total.max_frontier = max(
                stats_total.max_frontier,
                len(beam),
            )
            stats_total.depth_hist[depth] = (
                stats_total.depth_hist.get(depth, 0)
                + len(beam)
            )

            if not beam:
                break

        pred = found

        if pred:
            predicted_positive += 1
            stats_total.proof_checks += 1

            # Exact proof verification is intentionally simple and strict:
            # a returned positive must end in the requested relation/object.
            proof_valid = (
                bool(found_path)
                and found_path[-1][1]
                == case.target_relation
                and found_path[-1][2]
                == case.object
            )

            if not proof_valid:
                pred = False
            else:
                path_lengths.append(
                    len(found_path)
                )

        if pred:
            if case.gold:
                correct += 1
                supported_correct += 1
            else:
                false_positive += 1
        elif not case.gold:
            correct += 1

        total_steps += steps

        case_reports.append({
            "case": idx,
            "gold": bool(case.gold),
            "predicted_positive": bool(pred),
            "steps": steps,
            "path_length": len(found_path)
            if found_path
            else 0,
            "elapsed_seconds":
                time.perf_counter()
                - case_started,
        })

        if (
            progress_every > 0
            and (
                idx == 1
                or idx % progress_every == 0
                or idx == total
            )
        ):
            elapsed = time.perf_counter() - started
            rate = idx / max(
                elapsed,
                1e-9,
            )
            eta = (
                (total - idx)
                / max(rate, 1e-9)
            )

            print(
                f"    [CASE {idx}/{total}] "
                f"goal_directed "
                f"rate={rate:.2f}/s "
                f"elapsed={elapsed:.1f}s "
                f"eta={eta:.1f}s "
                f"beam={len(beam) if 'beam' in locals() else 0} "
                f"cache={len(per_job_cache):,} "
                f"exp={stats_total.expansions:,}",
                flush=True,
            )

    accuracy = (
        correct / max(
            1,
            total,
        )
    )

    supported_recovery = (
        supported_correct / max(
            1,
            supported,
        )
    )

    false_rate = (
        false_positive / max(
            1,
            negatives,
        )
    )

    return {
        "accuracy": accuracy,
        "supported_cases": supported,
        "supported_recovery": supported_recovery,
        "negative_cases": negatives,
        "false_proof_rate": false_rate,
        "predicted_positive": predicted_positive,
        "mean_steps": (
            total_steps / max(1, total)
        ),
        "mean_path_length": (
            sum(path_lengths)
            / max(
                1,
                len(path_lengths),
            )
        ),
        "budget_exhausted": 0,
        "controller_stats": vars(stats_total),
        "policy_seconds": (
            time.perf_counter() - started
        ),
        "case_reports": case_reports,
    }


def run_one(job: Job, args, cases, profiles, neighbors):
    started = time.perf_counter()
    con = connect_readonly(args.database)

    try:
        log(
            f"[JOB {job.index:03d}/{job.total:03d}] START "
            f"seed={job.seed} policy={job.policy}"
        )

        # V590 is intentionally a single new search policy. We retain the
        # matrix/seed structure so it is directly comparable with V585.
        result = goal_directed_policy(
            con=con,
            cases=cases,
            budget=args.budget,
            per_node=args.per_node,
            max_depth=args.max_depth,
            profiles=profiles,
            neighbors=neighbors,
            seed=job.seed,
            max_case_seconds=args.max_case_seconds,
            progress_every=args.progress_every,
        )

        elapsed = time.perf_counter() - started
        log(
            f"[JOB {job.index:03d}/{job.total:03d}] END   "
            f"seed={job.seed} policy={job.policy} "
            f"acc={result['accuracy']:.4f} "
            f"recover={result['supported_recovery']:.4f} "
            f"false={result['false_proof_rate']:.4f} "
            f"steps={result['mean_steps']:.2f} "
            f"elapsed={elapsed:.1f}s"
        )

        return {
            "job": asdict(job),
            "elapsed_seconds": elapsed,
            "result": result,
        }

    finally:
        con.close()


def normalize_result(row):
    """
    Make heterogeneous V575 evaluator return shapes JSON-safe.
    """
    result = row.get("result")
    if isinstance(result, dict):
        out = dict(result)
    elif hasattr(result, "__dict__"):
        out = dict(result.__dict__)
    elif isinstance(result, tuple):
        out = {"tuple": list(result)}
    else:
        out = {"value": result}

    row = dict(row)
    row["result"] = out
    return row


def main():
    # V590 preflight: verify the embedded controller API and immutable Case
    # schema before touching the 44+ GB graph.
    import inspect as _inspect
    _preflight_eval = getattr(v575, "evaluate_policy", None)
    _preflight_case = getattr(v575, "Case", None) or getattr(v575, "QueryCase", None)
    if _preflight_eval is None:
        raise RuntimeError(
            "Embedded controller does not expose evaluate_policy()."
        )
    if _preflight_case is None:
        raise RuntimeError(
            "Embedded controller exposes neither Case nor QueryCase."
        )
    log(
        f"[CONTROLLER API] evaluate_policy{_inspect.signature(_preflight_eval)}"
    )
    log(
        f"[CASE SCHEMA] {_preflight_case.__name__}{_inspect.signature(_preflight_case)}"
    )

    ap = argparse.ArgumentParser(
        description="V590 parallel cognitive benchmark matrix"
    )

    ap.add_argument("--database", required=True)
    ap.add_argument("--v568", required=True)
    ap.add_argument("--output", required=True)

    ap.add_argument("--workers", type=int, default=20)
    ap.add_argument("--seeds", type=int, default=5)
    ap.add_argument("--seed-start", type=int, default=57600)

    ap.add_argument("--budget", type=int, default=80)
    ap.add_argument("--per-node", type=int, default=60)
    ap.add_argument("--max-depth", type=int, default=3)

    ap.add_argument("--cache-entries", type=int, default=12000)
    ap.add_argument("--progress-every", type=int, default=10)
    ap.add_argument("--max-probes-per-case", type=int, default=500)
    ap.add_argument("--max-case-seconds", type=float, default=2.0)

    ap.add_argument("--top-predicates", type=int, default=20)
    ap.add_argument("--sample-each", type=int, default=600)
    ap.add_argument("--middle-limit", type=int, default=150)
    ap.add_argument("--case-cap", type=int, default=100)
    ap.add_argument("--supported-per-relation", type=int, default=20)
    ap.add_argument("--negative-per-relation", type=int, default=20)

    ap.add_argument("--only-policy", default="")
    ap.add_argument("--skip-bfs", action="store_true")
    ap.add_argument("--skip-depth-branch", action="store_true")

    args = ap.parse_args()

    db = Path(args.database)
    if not db.exists():
        raise FileNotFoundError(db)

    log("=== V590 PARALLEL COGNITIVE MATRIX ===")
    log(f"database             : {db.resolve()}")
    log(f"database size        : {db.stat().st_size / (1024**3):.2f} GB")
    log(f"V568 profiles        : {Path(args.v568).resolve()}")
    log(f"workers              : {args.workers}")
    log(f"seeds                : {args.seeds}")
    log(f"global jobs          : policies × seeds")
    log(f"cache/job            : {args.cache_entries:,}")
    log("source graph         : READ-ONLY")
    log("mode                 : parallel policy/seed jobs")
    log("nested parallelism   : OFF")

    if args.workers < 1 or args.workers > 20:
        raise ValueError("--workers must be between 1 and 20")

    # Main-process connection: oracle/profile discovery happens once.
    con = connect_readonly(str(db))
    try:
        profiles = load_profiles(args)
        oracle = discover_oracle(args, con)
    finally:
        con.close()

    # Normalize common oracle return shapes.
    if isinstance(oracle, tuple):
        cases = oracle[0]
        neighbors = oracle[1] if len(oracle) > 1 else {}
    elif isinstance(oracle, dict):
        cases = oracle.get("cases", oracle.get("oracle", []))
        neighbors = oracle.get("neighbors", {})
    else:
        cases = oracle
        neighbors = {}

    cases = list(cases)

    all_policies = ["goal_directed"]

    policies = ["goal_directed"]

    jobs = []
    total = len(policies) * args.seeds

    for seed_offset in range(args.seeds):
        seed = args.seed_start + seed_offset
        for policy in policies:
            jobs.append(
                Job(
                    index=len(jobs) + 1,
                    total=total,
                    seed=seed,
                    policy=policy,
                )
            )

    log("")
    log("=== MATRIX ===")
    log(f"policies             : {len(policies)}")
    log(f"seeds                : {args.seeds}")
    log(f"jobs                 : {total}")
    log(f"cases/job            : {len(cases)}")
    log(f"parallel workers     : {args.workers}")
    log("")

    started = time.perf_counter()
    results = []
    failures = []

    # No nested executors: exactly args.workers graph-reading jobs maximum.
    with ThreadPoolExecutor(
        max_workers=args.workers,
        thread_name_prefix="v576",
    ) as pool:
        future_map = {
            pool.submit(
                run_one,
                job,
                args,
                cases,
                profiles,
                neighbors,
            ): job
            for job in jobs
        }

        completed = 0

        for future in as_completed(future_map):
            job = future_map[future]
            completed += 1

            try:
                row = normalize_result(
                    future.result()
                )
                results.append(row)

                elapsed = time.perf_counter() - started
                rate = completed / max(
                    elapsed,
                    1e-9,
                )
                remaining = total - completed
                eta = remaining / max(
                    rate,
                    1e-9,
                )

                log(
                    f"[MATRIX {completed:03d}/{total:03d}] "
                    f"finished={job.policy}@{job.seed} "
                    f"rate={rate:.2f} jobs/s "
                    f"elapsed={elapsed:.1f}s "
                    f"eta={eta:.1f}s"
                )

            except Exception as exc:
                elapsed = time.perf_counter() - started

                failures.append({
                    "job": asdict(job),
                    "error": f"{type(exc).__name__}: {exc}",
                    "traceback": traceback.format_exc(),
                })

                log(
                    f"[MATRIX {completed:03d}/{total:03d}] "
                    f"ERROR={job.policy}@{job.seed} "
                    f"{type(exc).__name__}: {exc} "
                    f"elapsed={elapsed:.1f}s"
                )

    elapsed = time.perf_counter() - started

    payload = {
        "version": "V590",
        "config": vars(args),
        "policies": policies,
        "jobs": total,
        "cases": len(cases),
        "results": sorted(
            results,
            key=lambda r: (
                r["job"]["seed"],
                r["job"]["policy"],
            ),
        ),
        "failures": failures,
        "elapsed_seconds": elapsed,
    }

    Path(args.output).parent.mkdir(
        parents=True,
        exist_ok=True,
    )
    Path(args.output).write_text(
        json.dumps(
            payload,
            indent=2,
            default=str,
        ),
        encoding="utf-8",
    )

    log("")
    log("========================================================================")
    log("V590 COMPLETE")
    log("========================================================================")
    log(f"jobs completed        : {len(results)}/{total}")
    log(f"job failures          : {len(failures)}")
    log(f"elapsed               : {elapsed:.1f}s")
    log(f"JSON                  : {Path(args.output).resolve()}")

    if failures:
        log("WARNING: one or more jobs failed; see JSON failures[]")


if __name__ == "__main__":
    main()
